package org.sleepwell.app;
import android.app.*;import android.content.*;import android.os.*;import android.text.*;import android.view.*;import android.widget.*;import androidx.activity.*;import org.json.*;import java.util.*;
/** Private explicit enrollment/preview/challenge. Images exist only in the owned live camera pipeline. */
public final class PictureMatchActivity extends ComponentActivity {
    static final int ENROLL=788,CHALLENGE=789,PREVIEW=790,FALLBACK=RESULT_FIRST_USER;private String request,run="",label="",error="",status="Camera stays off until you start.",mode="enroll";private int unit=-1;private PictureReference reference;private PictureSignature latest;private long latestAt,generation,started;private boolean resumed,pending,released=true;private CameraTaskOwner cameraOwner;private PictureCamera.Port camera;private PictureCamera.Factory cameras;private PictureCameraAccess.Port access;private PictureHold hold;private TextView liveStatus;private final Handler handler=new Handler(Looper.getMainLooper());
    static Intent enroll(Activity owner,PictureReference reference,String request){Intent intent=RecordUi.intent(owner,PictureMatchActivity.class).putExtra("mode","enroll").putExtra("request",request);if(reference!=null)intent.putExtra("reference",PictureReferenceJson.encode(reference).toString());return intent;}
    static Intent challenge(Activity owner,PictureReference reference,String run,int unit,String request){return enroll(owner,reference,request).putExtra("mode","challenge").putExtra("run",run).putExtra("unit",unit);}
    private final Runnable verify=new Runnable(){public void run(){if(!resumed)return;if(!current()){stop();setResult(RESULT_CANCELED);finish();return;}if(cameraOwner.pending(PictureMatchActivity.this)){completePending();handler.postDelayed(this,250);return;}if(cameraOwner.closing(PictureMatchActivity.this)){if(stop())render();handler.postDelayed(this,250);return;}if(camera!=null&&SystemClock.elapsedRealtime()-started>=60000){stop();error="The one-minute camera attempt ended. Start again or use Math.";render();}handler.postDelayed(this,250);}};
    @Override public void onCreate(Bundle saved){super.onCreate(saved);RecordUi.review(this);access=PictureCameraAccess.port;cameras=PictureCamera.factory;try{request=getIntent().getStringExtra("request");if(request==null||!UUID.fromString(request).toString().equals(request))throw new IllegalArgumentException();mode=getIntent().getStringExtra("mode");if(!Set.of("enroll","preview","challenge").contains(mode))throw new IllegalArgumentException();run=getIntent().getStringExtra("run");if(run==null)run="";unit=getIntent().getIntExtra("unit",-1);String raw=saved==null?getIntent().getStringExtra("reference"):saved.getString("reference");if(raw!=null){reference=PictureReferenceJson.decode(new JSONObject(raw));label=reference.label;}if(!mode.equals("enroll")&&reference==null||mode.equals("challenge")&&(run.isEmpty()||unit<0))throw new IllegalArgumentException();if(saved!=null){label=saved.getString("label",label);error=saved.getString("error","");status="Camera paused. Start again when ready.";}if(reference!=null)hold=new PictureHold(reference.signature);}catch(Exception invalid){finish();return;}cameraOwner=CameraTaskOwner.attach(this,new JSONArray(java.util.Arrays.asList(getClass().getName(),mode,run,unit,request,reference==null?"":reference.key())).toString(),saved);if(mode.equals("challenge")){setShowWhenLocked(true);setTurnScreenOn(true);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);}getOnBackPressedDispatcher().addCallback(this,new OnBackPressedCallback(true){public void handleOnBackPressed(){back();}});render();}
    private boolean current(){if(!resumed)return false;if(!mode.equals("challenge"))return true;try{if(!AlarmService.current(this,run)||Prefs.number(this,"challengeCompleted",-1)!=unit)return false;Alarm alarm=Alarm.read(new JSONObject(Prefs.text(this,"active_alarm","{}")));ChallengeRoutine.Position position=alarm.challenges().at(unit);return position!=null&&position.task.type.equals("Picture match")&&position.task.picture!=null&&position.task.picture.key().equals(reference.key());}catch(Exception invalid){return false;}}
    @Override protected void onResume(){super.onResume();resumed=true;if(!current()){finish();return;}verify.run();if(pending&&access.status(this)==PictureCameraAccess.Status.READY){pending=false;begin();}else if(camera==null)render();}
    @Override protected void onPause(){resumed=false;handler.removeCallbacks(verify);if(camera!=null)status="Camera paused. Start again when ready.";stop();super.onPause();}
    private void render(){LinearLayout body=Design.page(this,false,null,n->{});RecordUi.header(body,mode.equals("enroll")?"Add a picture reference":mode.equals("preview")?"Picture match preview":"Match your picture",this::back);Design.space(body,10);if(cameraOwner!=null&&(cameraOwner.pending(this)||cameraOwner.closing(this))){cleanupView(body);return;}Design.text(body,"Local visual similarity, not object identity or liveness. Reframe the same view if lighting or composition changes.",13,400,Design.MUTED);Design.space(body,12);if(mode.equals("enroll")){Design.text(body,"Reference name",13,500,Design.MUTED);EditText name=new EditText(this);name.setSingleLine(true);name.setText(label);name.setHint("Bathroom shelf");name.setContentDescription("Picture reference name");name.setTextColor(Design.INK);name.setTextSize(16*Appearance.scale(this));name.setTypeface(Design.font(this,400));name.setFilters(new InputFilter[]{new InputFilter.LengthFilter(60)});name.setBackground(Design.outline(this,Design.CREAM,Design.LINE,12));Design.pad(name,14,12);body.addView(name,new LinearLayout.LayoutParams(-1,Design.dp(this,52)));name.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence text,int start,int count,int after){}public void onTextChanged(CharSequence text,int start,int before,int count){label=text.toString();}public void afterTextChanged(Editable text){}});}else Design.text(body,reference.label,18,600,Design.BROWN);Design.space(body,12);
        FrameLayout frame=new FrameLayout(this);frame.setContentDescription("Picture camera preview");frame.setBackground(Design.shape(this,Design.SOFT,18));frame.setClipToOutline(true);if(camera!=null){View preview=camera.preview();if(preview.getParent() instanceof ViewGroup parent)parent.removeView(preview);frame.addView(preview,new FrameLayout.LayoutParams(-1,-1));}else{TextView empty=Design.text(this,reference==null?"Start camera to capture a reference":"Reference signature saved · no photo stored",14,500,Design.MUTED);empty.setGravity(Gravity.CENTER);Design.pad(empty,18,18);frame.addView(empty,new FrameLayout.LayoutParams(-1,-1));}int side=Math.min(260,(int)(getResources().getDisplayMetrics().widthPixels/getResources().getDisplayMetrics().density)-48);LinearLayout.LayoutParams square=new LinearLayout.LayoutParams(Design.dp(this,side),Design.dp(this,side));square.gravity=Gravity.CENTER_HORIZONTAL;body.addView(frame,square);Design.space(body,10);liveStatus=Design.text(body,status,14,500,Design.BROWN);liveStatus.setContentDescription("Picture scan status");liveStatus.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);
        PictureCameraAccess.Status permission=access.status(this);if(camera==null){String action=permission==PictureCameraAccess.Status.NEEDED?"Allow picture camera":permission==PictureCameraAccess.Status.SETTINGS?"Open picture camera settings":"Start picture camera";Button start=Design.button(body,action,false,this::startPressed);if(permission==PictureCameraAccess.Status.UNSUPPORTED){start.setEnabled(false);Design.text(body,"No supported camera is available. Use Math instead.",13,400,Design.MUTED);}}else{if(mode.equals("enroll"))Design.button(body,"Capture reference",true,this::captureReference);Design.button(body,"Pause picture camera",false,()->{stop();status="Camera paused. Start again when ready.";render();});}
        if(mode.equals("enroll")&&reference!=null&&camera==null){Design.text(body,"Reference captured",14,600,0xff16732e);Design.button(body,"Try picture match",false,()->{String nonce=UUID.randomUUID().toString();startActivityForResult(enroll(this,reference,nonce).putExtra("mode","preview"),PREVIEW);});}LinearLayout footer=RecordUi.footer(body);if(!error.isEmpty()){TextView problem=Design.text(footer,error,13,500,0xffa93919);problem.setContentDescription("Picture scan error");problem.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);}if(mode.equals("enroll"))Design.button(footer,"Save picture reference",true,this::save);else Design.button(footer,"Use Math fallback",false,()->respond(FALLBACK,0));
    }
    private void startPressed(){error="";PictureCameraAccess.Status permission=access.status(this);if(permission==PictureCameraAccess.Status.READY){pending=false;begin();return;}if(permission==PictureCameraAccess.Status.UNSUPPORTED){error="No supported camera is available.";render();return;}pending=true;try{access.request(this);}catch(RuntimeException invalid){pending=false;error="Camera access could not open. Check Android app settings or use Math.";render();}}
    private void begin(){if(!current()||access.status(this)!=PictureCameraAccess.Status.READY)return;if(!stop()){error="Camera could not close. Reopen this screen or return to Math.";render();return;}long ticket=++generation;latest=null;if(hold!=null)hold.reset();try{camera=cameras.create(this);released=false;cameraOwner.bind(this,camera::close,camera::released);started=SystemClock.elapsedRealtime();status="Keep the same detailed view inside the square.";camera.start(new PictureCamera.Listener(){public void frame(PictureSignature signature,long captured,String issue){if(ticket!=generation||camera==null||!current())return;long now=SystemClock.elapsedRealtime();if(access.status(PictureMatchActivity.this)!=PictureCameraAccess.Status.READY){stop();error="Camera access changed. Use Math or allow access again.";render();return;}if(signature==null||captured>now||captured<0||now-captured>800){latest=null;if(hold!=null)hold.reset();status=issue==null||issue.isBlank()?"Use a brighter, textured picture with visible detail.":issue;}else{latest=signature;latestAt=captured;if(mode.equals("enroll"))status="Detailed frame ready. Tap Capture reference.";else if(hold.frame(signature,captured,now)){respond(RESULT_OK,captured);return;}else status=reference.signature.matches(signature)?"Hold steady · "+hold.progress()+" of 3 frames":"Different view. Match the enrolled framing and lighting.";}if(liveStatus!=null)liveStatus.setText(status);}public void error(String message){if(ticket!=generation||!current())return;stop();error=message;render();}});render();}catch(RuntimeException unavailable){stop();error="Picture camera could not start. Try again or use Math.";render();}}
    private boolean stop(){generation++;latest=null;if(hold!=null)hold.reset();if(cameraOwner==null)return camera==null;released=cameraOwner.stop(this);if(released)camera=null;return released;}
    private void captureReference(){long now=SystemClock.elapsedRealtime();if(!current()||latest==null||now<latestAt||now-latestAt>800){error="Wait for a fresh, detailed camera frame before capturing.";render();return;}try{PictureReference captured=new PictureReference(label,latest);cameraOwner.earn(this,2,latestAt,new Intent().putExtra("reference",PictureReferenceJson.encode(captured).toString()));stop();if(!completePending())render();}catch(IllegalArgumentException invalid){error=invalid.getMessage();render();}}
    private void save(){try{if(camera!=null)throw new IllegalArgumentException("Capture this view first, or pause the camera to keep the existing reference.");if(reference==null)throw new IllegalArgumentException("Capture a detailed reference first.");PictureReference saved=new PictureReference(label,reference.signature);if(!stop())throw new IllegalStateException("Camera could not close. Reopen this screen.");setResult(RESULT_OK,new Intent().putExtra("request",request).putExtra("reference",PictureReferenceJson.encode(saved).toString()));finish();}catch(IllegalArgumentException|IllegalStateException invalid){error=invalid.getMessage();render();}}
    private void respond(int result,long captured){if(!current())return;cameraOwner.earn(this,result,captured,new Intent().putExtra("request",request).putExtra("run",run).putExtra("unit",unit).putExtra("key",reference.key()).putExtra("captured",captured));stop();if(!completePending())render();}
 private boolean completePending(){
  if(!current()||!hasWindowFocus()||!getWindow().getDecorView().isAttachedToWindow()||!cameraOwner.pending(this)||!cameraOwner.clean())return false;
  CameraTaskOwner.Pending earned=cameraOwner.take(this);if(earned==null)return false;camera=null;released=true;
  if(earned.result==2){try{reference=PictureReferenceJson.decode(new JSONObject(earned.data.getStringExtra("reference")));status="Only the compact visual signature is kept.";error="";}catch(Exception invalid){error="The captured reference could not be restored. Capture again.";}render();return true;}
  if(mode.equals("preview")){status=earned.result==RESULT_OK?"Picture matched":"Math fallback selected";error="";mode="previewDone";LinearLayout body=Design.page(this,false,null,n->{});RecordUi.header(body,"Picture match preview",this::back);Design.text(body,status,24,600,Design.BROWN);Design.fixedAction(body,"Return to reference",this::back);return true;}
  setResult(earned.result,earned.data);finish();return true;
 }
 private void cleanupView(LinearLayout body){
  Design.text(body,"Release camera",25,600,Design.INK);Design.space(body,12);
  Design.text(body,"Camera callbacks are stopped. Continue after this attempt’s camera and analysis have fully closed. Any earned result is retained.",14,400,Design.MUTED);
  Design.button(body,"Retry camera cleanup",true,()->{if(!current()||!hasWindowFocus())return;stop();if(!completePending())render();});Design.fixedAction(body,"Cancel",this::back);
 }
    private void back(){pending=false;if(cameraOwner!=null)cameraOwner.cancel(this);stop();setResult(RESULT_CANCELED);finish();}
    @Override public void onRequestPermissionsResult(int code,String[] permissions,int[] grants){super.onRequestPermissionsResult(code,permissions,grants);if(code!=PictureCameraAccess.REQUEST)return;if(access.status(this)==PictureCameraAccess.Status.READY){pending=false;if(resumed)begin();else pending=true;}else{pending=false;error="Camera access was not allowed. Keep editing or use Math.";render();}}
    @Override protected void onActivityResult(int code,int result,Intent data){super.onActivityResult(code,result,data);if(code==PREVIEW){status="Camera stays off until you start.";render();}}
    @Override protected void onSaveInstanceState(Bundle saved){super.onSaveInstanceState(saved);if(cameraOwner!=null)cameraOwner.save(this,saved);saved.putString("label",label);saved.putString("error",error);if(reference!=null)saved.putString("reference",PictureReferenceJson.encode(reference).toString());}
    @Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(focused)RecordUi.lightBars(this);}
    @Override protected void onDestroy(){handler.removeCallbacksAndMessages(null);stop();if(cameraOwner!=null)cameraOwner.detach(this,isChangingConfigurations());super.onDestroy();}
}
